attribute-closure.pseudocode:
def closure(X, fds):
    # fds: [(좌변 집합, 우변 집합), ...]
    result = set(X)
    changed = True
    while changed:  # 더 이상 늘지 않을 때까지 반복
        changed = False
        for lhs, rhs in fds:
            if lhs <= result and not rhs <= result:
                result |= rhs  # 결정자 포함 시 종속 속성 추가
                changed = True
    return result

def is_superkey(X, fds, attrs):
    return closure(X, fds) >= set(attrs)

def is_candidate_key(X, fds, attrs):
    # 슈퍼키이면서 원소 하나만 빼도 슈퍼키가 아니어야 함
    return is_superkey(X, fds, attrs) and all(
        not is_superkey(set(X) - {a}, fds, attrs)
        for a in X)
